# -*- coding: utf-8 -*-
"""TOJI HOST — Combined Telegram Hosting Bot
Single-process integration with one Telegram bot, one Flask app and one SQLite DB.
Configure all secrets through environment variables; never commit your .env file.
"""
import os, sys, zlib, base64, threading, logging, time, atexit
from pathlib import Path
from flask import Flask
import telebot
from telebot import types
from dotenv import load_dotenv
load_dotenv()

REQUIRED_TOKEN = os.getenv("BOT_TOKEN") or os.getenv("TOKEN")
if not REQUIRED_TOKEN:
    raise SystemExit("ERROR: Set BOT_TOKEN (or TOKEN) environment variable.")
OWNER_ID = int(os.getenv("OWNER_ID", "0"))
if OWNER_ID <= 0:
    raise SystemExit("ERROR: Set OWNER_ID to your Telegram numeric user ID.")
DATA_ROOT = Path(os.getenv("DATA_DIR", str(Path(__file__).resolve().parent)))
SHARED_DATA_DIR = str(DATA_ROOT / "inf")
SHARED_UPLOAD_DIR = str(DATA_ROOT / "hostings")
os.makedirs(SHARED_DATA_DIR, exist_ok=True)
os.makedirs(SHARED_UPLOAD_DIR, exist_ok=True)
shared_app = Flask("combined_hosting_bot")
shared_app.config["MAX_CONTENT_LENGTH"] = 25 * 1024 * 1024
shared_bot = telebot.TeleBot(REQUIRED_TOKEN, parse_mode=None, threaded=True)
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(name)s: %(message)s")
log = logging.getLogger("toji-host")

