# Load both feature sets in isolated namespaces to avoid Python global-name collisions.
REAL = {"__name__": "realhosting_features", "__file__": __file__, "__builtins__": __builtins__,
        "shared_bot": shared_bot, "shared_app": shared_app, "REQUIRED_TOKEN": REQUIRED_TOKEN,
        "SHARED_DATA_DIR": SHARED_DATA_DIR, "SHARED_UPLOAD_DIR": SHARED_UPLOAD_DIR}
HOST = {"__name__": "host_features", "__file__": __file__, "__builtins__": __builtins__,
        "shared_bot": shared_bot, "shared_app": shared_app, "REQUIRED_TOKEN": REQUIRED_TOKEN,
        "SHARED_DATA_DIR": SHARED_DATA_DIR, "SHARED_UPLOAD_DIR": SHARED_UPLOAD_DIR}
exec(compile(_HOST_SOURCE, "host.py [integrated]", "exec"), HOST)
exec(compile(_REALHOSTING_SOURCE, "RealHosting.py [integrated]", "exec"), REAL)

# Premium persistent Telegram Reply Keyboard (shown above the message input).
def _premium_reply_menu(uid):
    markup = types.ReplyKeyboardMarkup(resize_keyboard=True, row_width=2, one_time_keyboard=False)
    rows = [
        ("📤 Upload File", "📂 My Files"),
        ("📝 Paste Code", "📦 Requirements.txt"),
        ("⭐ GitHub Run", "⚡ Speed Test"),
        ("💰 Balance", "💎 Buy Plan"),
        ("💎 My Plan", "💳 Manual UPI QR"),
        ("📡 UptimeRobot", "📢 Updates"),
        ("📞 Contact Owner",),
    ]
    if uid in REAL.get("admin_ids", set()):
        rows.extend([
            ("📊 Stats", "💳 Subs"),
            ("🔒 Lock", "🔓 Unlock"),
            ("🟢 Run All", "📢 Broadcast"),
            ("👑 Admin",),
        ])
    for row in rows:
        markup.row(*[types.KeyboardButton(label) for label in row])
    return markup

REAL["create_cube_menu"] = _premium_reply_menu

# Route all inline callbacks through exactly one dispatcher.
def _combined_callback(call):
    data = call.data or ""
    host_prefixes = (
        "upload", "check_files", "file_", "start_", "stop_", "restart_", "delete_", "logs_",
        "speed", "back_to_main", "confirm_broadcast_", "cancel_broadcast", "manual_install",
        "subscription", "stats", "lock_bot", "unlock_bot", "run_all_scripts", "broadcast",
        "admin_panel", "add_admin", "remove_admin", "list_admins", "add_subscription",
        "remove_subscription", "check_subscription", "user_management", "ban_user", "unban_user",
        "user_info", "all_users", "set_user_limit", "remove_user_limit", "admin_settings",
        "system_info", "bot_performance", "cleanup_files", "install_logs", "admin_install",
        "manage_mandatory_channels", "add_mandatory_channel", "remove_mandatory_channel",
        "list_mandatory_channels", "remove_channel_", "check_subscription_status",
        "approve_file_", "reject_file_", "approve_zip_", "reject_zip_"
    )
    if data.startswith("users_page_"):
        return HOST["handle_users_page"](call)
    if data.startswith(host_prefixes):
        return HOST["handle_callbacks"](call)
    return REAL["callbacks"](call)
shared_bot.callback_query_handlers = []
shared_bot.callback_query_handler(func=lambda call: True)(_combined_callback)

# Central /start and /help retain the payment-enabled menu while applying host.py access checks.
@shared_bot.message_handler(commands=["start"])
def combined_start(message):
    uid = message.from_user.id
    if HOST["is_user_banned"](uid):
        return shared_bot.reply_to(message, "❌ You are banned from using this bot.")
    subscribed, missing = HOST["check_mandatory_subscription"](uid)
    if not subscribed and uid not in HOST["admin_ids"]:
        msg, markup = HOST["create_subscription_check_message"](missing)
        return shared_bot.reply_to(message, msg, reply_markup=markup, parse_mode="Markdown")
    if HOST.get("bot_locked", False) and uid not in HOST["admin_ids"]:
        return shared_bot.reply_to(message, "⚠️ Bot is locked by admin. Try later.")
    return REAL["start"](message)

@shared_bot.message_handler(commands=["help"])
def combined_help(message):
    return REAL["help_cmd"](message)

# Both payment rails: FamWay auto-verification (/customqr) and manual UPI QR (/manualqr).
# User-provided fixed manual UPI QR (embedded so the bot remains a single-file project).
_MANUAL_UPI_QR_B64 = """"""

@shared_bot.message_handler(func=lambda message: (message.text or "") == "💳 Manual UPI QR")
def manual_qr_menu_button(message):
    return manual_qr_command(message)

@shared_bot.message_handler(commands=["manualqr"])
def manual_qr_command(message):
    try:
        parts = (message.text or "").split(maxsplit=1)
        amount_text = parts[1].strip() if len(parts) > 1 else ""
        if amount_text:
            try:
                amount = int(amount_text)
                if amount < 1 or amount > 50000:
                    raise ValueError
            except ValueError:
                return shared_bot.reply_to(message, "Use: /manualqr or /manualqr AMOUNT (1-50000)")
            caption_amount = f"\nAmount to pay: ₹{amount}"
        else:
            caption_amount = "\nEnter the amount agreed with admin."

        qr_path = DATA_ROOT / "manual_upi_qr.png"
        qr_path.write_bytes(base64.b64decode(_MANUAL_UPI_QR_B64))
        with open(qr_path, "rb") as qr_file:
            return shared_bot.send_photo(
                message.chat.id,
                qr_file,
                caption=(
                    "MANUAL UPI PAYMENT\n"
                    "Scan this QR using any UPI app.\n"
                    "UPI ID: rohit.hacrr@fam"
                    + caption_amount
                    + "\nAfter payment, send the 12-digit UTR/reference number to admin. "
                      "Balance is added only after admin verifies the payment."
                )
            )
    except Exception as exc:
        log.exception("manual QR failed")
        return shared_bot.reply_to(message, f"Could not send manual UPI QR: {exc}")

@shared_app.route("/health")
def health():
    return {"status": "ok", "service": "toji-host-bot"}, 200

@shared_app.route("/ping")
def web_ping():
    return "ALIVE - 200 OK", 200

def _run_web():
    port = int(os.getenv("PORT", "8080"))
    shared_app.run(host="0.0.0.0", port=port, debug=False, use_reloader=False, threaded=True)

def main():
    if not os.getenv("FAMWAY_API_KEY"):
        log.warning("FAMWAY_API_KEY is unset: FamWay auto-pay will not work until configured.")
    if not os.getenv("BOT_URL"):
        log.warning("BOT_URL is unset: set your public HTTPS service URL for payment links/webhooks.")
    threading.Thread(target=_run_web, name="flask-server", daemon=True).start()
    for target in (REAL.get("auto_run_all_on_startup"), REAL.get("check_expiry_loop"),
                   REAL.get("auto_fix_and_restart_loop"), REAL.get("built_in_uptimerobot")):
        if callable(target):
            threading.Thread(target=target, daemon=True).start()
    log.info("TOJI HOST started. One Telegram polling loop active.")
    while True:
        try:
            shared_bot.infinity_polling(timeout=60, long_polling_timeout=30, skip_pending=True)
        except KeyboardInterrupt:
            break
        except Exception:
            log.exception("Telegram polling error; retrying in 5 seconds")
            time.sleep(5)

if __name__ == "__main__":
    main()
